{"meetingId": "854", "tickets": [
{"title": "Update household profile", "templateId": "5b32df43-64e8-57a6-a96f-81094794d36d", "text": "Have Alden Pebblefizz complete the remaining contact, authorization, risk tolerance, and communication preference sections of the household profile packet so the new client record for Alden and Priya Pebblefizz can be finalized. The packet was started but not finished during onboarding.", "priority": null, "dueDate": "2024-04-26", "assigneeId": null, "subTasks": [], "evidence": "Mira and Tobin asked him to complete the remaining contact, authorization, risk tolerance, and communication preference sections so the new client record can be finalized, and the agreed follow-up is completion of those remaining sections by 2024-04-26."},
{"title": "Reset portal access and confirm upload instructions", "templateId": null, "text": "Reset secure portal access and confirm upload instructions with both Alden and Priya Pebblefizz. Priya did not receive the secure portal invitation and Alden's upload attempt timed out when attaching the Velvet Acorn Custody brokerage statement.", "priority": null, "dueDate": "2024-04-23", "assigneeId": null, "subTasks": [], "evidence": "the agreed follow-up is to reset portal access and confirm upload instructions with both household decision-makers by 2024-04-23."},
{"title": "Confirm beneficiary designations across accounts", "templateId": null, "text": "Confirm current beneficiary designations across Alden Pebblefizz's retirement and insurance accounts. His Paper Otter Robotics benefits screenshot lists Priya as retirement plan beneficiary while his insurance summary names his sister as an older contingent beneficiary.", "priority": null, "dueDate": "2024-05-08", "assigneeId": null, "subTasks": [], "evidence": "confirmation of current beneficiary designations across retirement and insurance accounts is needed by 2024-05-08."},
{"title": "Obtain complete estate documents", "templateId": null, "text": "Obtain complete copies of Alden and Priya Pebblefizz's wills, powers of attorney, and healthcare directives. The uploaded estate folder contains only signature pages and an unsigned draft trust memo, and complete copies are required before the planning team can summarize the estate arrangement.", "priority": null, "dueDate": "2024-05-08", "assigneeId": null, "subTasks": [], "evidence": "complete copies are needed by 2024-05-08 before the planning team can summarize the estate arrangement."},
{"title": "Coordinate retirement plan rollover request", "templateId": "6d91b3c5-f350-52b1-949e-0902b766d90a", "text": "Manage the reusable retirement plan rollover process. Confirm the source plan type, destination account readiness, distribution method, tax withholding instructions, transfer restrictions, and documentation needed before the client initiates the rollover. Track receipt of funds and flag any tax, investment, or timing issues for advisor review. Evaluate Alden Pebblefizz's prior employer retirement plan at Willow Pudding Components (approximately $148,000, unreviewed since 2021) and possible rollover steps once the plan statement and distribution options are available.", "priority": "medium", "dueDate": "2024-05-03", "assigneeId": "a937bf6e-3ad5-5284-b240-883a5ae3e40a", "subTasks": [], "evidence": "The agreed follow-up is to address that evaluation once those records are available, due 2024-05-03."},
{"title": "Include equity award considerations in first planning meeting", "templateId": null, "text": "Include Paper Otter Robotics annual equity award election considerations in the first planning meeting agenda for Alden Pebblefizz, covering vesting concentration, tax withholding, and whether to sell shares after vesting.", "priority": null, "dueDate": "2024-05-10", "assigneeId": null, "subTasks": [], "evidence": "the agreed follow-up is to include those equity award considerations in the first planning meeting by 2024-05-10."},
{"title": "Collect tax returns and CPA authorization", "templateId": null, "text": "Obtain Alden and Priya Pebblefizz's most recent federal and Oregon tax returns and written permission to coordinate with their CPA, Rowan Thimblefern. These materials are needed to complete the tax baseline for the first plan build.", "priority": null, "dueDate": "2024-05-01", "assigneeId": null, "subTasks": [], "evidence": "those materials and authorization are needed by 2024-05-01."},
{"title": "Update education funding assumptions", "templateId": null, "text": "Update education funding assumptions for Nora Pebblefizz's recent interest in an out-of-state engineering program, which could materially change the household's education funding target and the 529 spending timeline for the Pocket Lantern College Savings accounts (combined value about $84,000).", "priority": null, "dueDate": "2024-05-15", "assigneeId": null, "subTasks": [], "evidence": "updated education funding assumptions are needed by 2024-05-15."}
]}
